import pyomo.environ as pyo

DATA = {
    "foods": ["Chicken", "Rice", "Broccoli", "Tofu", "Beans"],
    "nutrients": ["protein", "carbs", "calories"],
    "cost": {
        "Chicken": 4,
        "Rice": 8,
        "Broccoli": 7,
        "Tofu": 10,
        "Beans": 1,
    },
    "content": {
        # nutrient -> food -> amount per serving
        "protein":  {"Chicken": 18, "Rice": 12, "Broccoli": 13, "Tofu": 5,  "Beans": 10},
        "carbs":    {"Chicken": 6,  "Rice": 28, "Broccoli": 19, "Tofu": 16, "Beans": 20},
        "calories": {"Chicken": 142,"Rice": 88, "Broccoli": 137,"Tofu": 141,"Beans": 150},
    },
    "requirement": {
        "protein": 56,
        "carbs": 194,
        "calories": 2012,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.FOODS = pyo.Set(initialize=d["foods"])
    model.NUTRIENTS = pyo.Set(initialize=d["nutrients"])

    model.x = pyo.Var(model.FOODS, within=pyo.NonNegativeReals)

    def cost_rule(m):
        return sum(d["cost"][f] * m.x[f] for f in m.FOODS)

    model.obj = pyo.Objective(rule=cost_rule, sense=pyo.minimize)

    def nutrient_rule(m, n):
        return sum(d["content"][n][f] * m.x[f] for f in m.FOODS) >= d["requirement"][n]

    model.nutrient_req = pyo.Constraint(model.NUTRIENTS, rule=nutrient_rule)

    return model


